import os
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from taf.ul.sc.perf.reports.kpi_report import KPIReport
from taf.ul.sc.perf.reports.banchmark_excel import BenchmarkExcel
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console


class LogsProcessingInterface(object):

    def processing_logs(self):
        lp = LogsProcessing(log_dir=self.pp.post_dir_path)
        lp.parsing_bts_logs()


class LogsProcessing(object):
    def __init__(self, log_dir=None, report_log_dir=None):
        self.log_dir = log_dir if log_dir else str(tc.output_dir)
        self.report_log_dir = report_log_dir if report_log_dir else os.path.join(self.log_dir, 'report')
        self.unix_local = UnixFunctionality(device_name="UnixLocal", autoconnect=True)
        self.generate_kpi_report = KPIReport(log_dir=self.log_dir, report_log_dir=self.report_log_dir)
        self.generate_benchmark_excel = BenchmarkExcel(log_dir=os.path.join(self.log_dir, 'debug'), dsp_log_dir=None)

    def parsing_bts_logs(self):
        # parsing cpu
        if tc.is_feature_enabled("generate_kpi_report"):
            self._generate_kpi_report()
        if tc.is_feature_enabled("collect_benchmark_stats"):
            if tc.is_feature_enabled("collect_benchmark_stats->collect_dsp_stats"):
                self.generate_benchmark_excel.dsp_log_dir = os.path.join(self.log_dir, 'moler')
            self._generate_benchmark_excel()

    def parsing_ue_logs(self):
        pass

    @log_function_status_to_console(msg="Generate BTS KPI Report", log_hierarchy=2, ignore_exception=True)
    @log_debug_function_info()
    def _generate_kpi_report(self):
        self.generate_kpi_report()

    @log_function_status_to_console(msg="Generate Benchmark Excel", log_hierarchy=2, ignore_exception=True)
    @log_debug_function_info()
    def _generate_benchmark_excel(self):
        self.generate_benchmark_excel()
